+package ledger
+
+import "testing"
+
+func TestBalanceMultiplePostings(t *testing.T) {
+	l := &Ledger{}
+
+	// Credit 300 to account "a", debited from "other"
+	if err := l.Post(
+		Entry{AccountID: "a", AmountCents: 300, Currency: "EUR"},
+		Entry{AccountID: "other", AmountCents: -300, Currency: "EUR"},
+	); err != nil {
+		t.Fatal(err)
+	}
+
+	// Debit 100 from account "a", credited to "other"
+	if err := l.Post(
+		Entry{AccountID: "a", AmountCents: -100, Currency: "EUR"},
+		Entry{AccountID: "other", AmountCents: 100, Currency: "EUR"},
+	); err != nil {
+		t.Fatal(err)
+	}
+
+	if got := l.Balance("a"); got != 200 {
+		t.Fatalf("balance(a) = %d, want 200", got)
+	}
+}

